function calculateCharge(order: Order) {
  let charge = 0;
  if (order.type === 'premium' && order.items.length > 5) {
    charge = order.items.reduce((s, i) => s + i.price, 0) * 0.9;
  } else if (order.type === 'standard') {
    if (order.customer.vip) charge = 0;
    else charge = order.items.reduce((s, i) => s + i.price, 0);
  } else {
    charge = order.items.reduce((s, i) => s + i.price, 0) + 5;
  }
  return charge;
}

function applyDiscount(order: Order, isBlackFriday: boolean) {
  let discount = 0;
  if (isBlackFriday) {
    discount = order.total * 0.3;
  } else if (order.customer.level === 'gold') {
    discount = order.total * 0.2;
  } else {
    discount = order.total * 0.05;
  }
  if (isBlackFriday) logPromo(order);
  return discount;
}

// Version A: single function with conditional branches
function price(order: Order) {
  if (order.type === 'A') {
    return basePrice(order) * 0.9 + rushFee(order);
  } else if (order.type === 'B') {
    return basePrice(order) + specialSurcharge(order);
  }
  return basePrice(order);
}

// Version B: extracted branch behaviors
function price(order: Order) {
  if (order.type === 'A') return priceForTypeA(order);
  if (order.type === 'B') return priceForTypeB(order);
  return defaultPrice(order);
}

function priceForTypeA(order: Order) { return basePrice(order) * 0.9 + rushFee(order); }
function priceForTypeB(order: Order) { return basePrice(order) + specialSurcharge(order); }
function defaultPrice(order: Order) { return basePrice(order); }
